from ta_ue_plugin_android.uepc.datatransfer.iperf_options import IPERF_CLIENT_OPTIONS, IPERF_SERVER_OPTIONS

# dt_name, duration, direction and protocol are not included here, because they are passed as separate arguments
# Should be in sync with https://confluence.ext.net.nokia.com/display/AbstractLibs/1.+Robot+keywords

ALLOWED_PLUGIN_KWARGS = {
    # TCP and UDP
    'app_server',
    'apn',
    'bandwidth',
    'interval',
    'iperf_path',
    'iperf_version',
    'port',
    'server_close_delay',
    'timeout',
    'throughput',
    'qci',
    'iperf_len',


    # Ping
    'allowed_packet_loss',
    'ping_count',
    'ping_host_ip',


    # HTTP
    'url',

    # FTP
    'host_ip',
    'local_path',
    'password',
    'remote_path',
    'user'
}

ALLOWED_ROBOT_KWARGS = \
    set(IPERF_CLIENT_OPTIONS['iperf2'].keys()) | \
    {"{}_{}".format(option, IPERF_CLIENT_OPTIONS['postfix']) for option in IPERF_CLIENT_OPTIONS['iperf2'].keys()} | \
    set(IPERF_SERVER_OPTIONS['iperf2'].keys()) | \
    {"{}_{}".format(option, IPERF_SERVER_OPTIONS['postfix']) for option in IPERF_SERVER_OPTIONS['iperf2'].keys()} | \
    ALLOWED_PLUGIN_KWARGS

ALLOWED_ROBOT_KWARGS_IPERF3 = \
    set(IPERF_CLIENT_OPTIONS['iperf3'].keys()) | \
    {"{}_{}".format(option, IPERF_CLIENT_OPTIONS['postfix']) for option in IPERF_CLIENT_OPTIONS['iperf3'].keys()} | \
    set(IPERF_SERVER_OPTIONS['iperf3'].keys()) | \
    {"{}_{}".format(option, IPERF_SERVER_OPTIONS['postfix']) for option in IPERF_SERVER_OPTIONS['iperf3'].keys()} | \
    ALLOWED_PLUGIN_KWARGS
